'use strict';
const E=window.BottegaEngine;
state.settings??={hourlyRate:100,policy:'median',markupPercent:0};state.settings.markupPercent??=0;
state.memory??={};state.answers??={};
document.querySelector('nav').insertAdjacentHTML('beforeend','<button data-view="settings">⚙ <span>Preferenze</span></button>');
document.querySelector('[data-view="settings"]').onclick=()=>show('settings');
document.querySelector('footer').insertAdjacentHTML('beforebegin',`<section id="settings" class="view" hidden><div class="heading"><div class="eyebrow">IL TUO MODO DI LAVORARE</div><h1>Preferenze.</h1><p>Ogni browser mantiene le proprie scelte e le proprie ricette apprese.</p></div><article class="card"><div class="fields"><label>Tariffa predefinita (€/ora)<input id="default-rate" type="number" min="0" max="100000" step="0.01"></label><label>Scelta componenti equivalenti<select id="default-policy"><option value="low">Più economica</option><option value="median">Mediana</option><option value="high">Più costosa</option></select></label></div><p>La mediana è l’articolo centrale per prezzo; con un numero pari si sceglie quello centrale meno caro. Nessuna preferenza modifica preventivi già creati.</p></article><article class="card memory-card"><h2>Memoria delle ricette</h2><p>Quando salvi una bozza generata, puoi ricordare materiali, quantità e ore per la stessa ricetta e gli stessi parametri. I prezzi vengono riletti dal listino e le alternative seguono la preferenza di prezzo corrente. Non si applicano correzioni tra browser diversi.</p><div id="memory-list"></div><button id="reset-memory" class="secondary">Azzera memoria delle ricette</button></article></section>`);
$('default-rate').value=state.settings.hourlyRate;$('default-policy').value=state.settings.policy;
$('default-rate').onchange=()=>{state.settings.hourlyRate=Math.min(100000,Math.max(0,Number($('default-rate').value)||0));$('default-rate').value=state.settings.hourlyRate;persist()};
$('default-policy').onchange=()=>{state.settings.policy=$('default-policy').value;persist()};
function memoryView(){$('memory-list').textContent=`${Object.keys(state.memory).length} configurazioni ricordate.`}memoryView();
$('reset-memory').onclick=()=>{if(!confirm('Cancellare risposte e correzioni ricordate? I preventivi restano invariati.'))return;state.memory={};state.answers={};persist();memoryView();recipeQuestions()};
document.querySelector('.editor-grid').insertAdjacentHTML('beforebegin',`<article class="card recipe-card"><div class="card-title"><h2>✳ Parti dal lavoro da svolgere</h2><span class="badge green">ELETTRICISTA</span></div><div class="fields"><label>Lavoro<select id="recipe-select">${E.recipes.map(r=>`<option value="${r.id}">${r.name}</option>`).join('')}</select></label><label>Scelta articoli per questo lavoro<select id="recipe-policy"><option value="default">Usa la preferenza salvata</option><option value="low">Più economica</option><option value="median">Mediana</option><option value="high">Più costosa</option></select></label></div><p id="recipe-description"></p><div class="fields recipe-questions"><label>Numero di punti<input id="recipe-count" type="number" value="1" min="1" max="1000" step="1"></label><label>Accessibilità<select id="recipe-access"><option value="normal">Ordinaria</option><option value="difficult">Difficoltosa (stima ore × 1,5)</option></select></label><label id="accessories-label">Supporti e placche<select id="recipe-accessories"><option value="no">Riutilizza quelli esistenti</option><option value="yes">Sostituisci anche supporti e placche</option></select></label></div><p id="recipe-memory" class="helper"></p><div class="recipe-actions"><button id="generate" class="primary">Genera bozza preventivo ↗</button><label class="check-label"><input id="learn-recipe" type="checkbox" checked> Al salvataggio ricorda le mie correzioni per lavori identici</label></div><p class="helper">Ricette e tempi dimostrativi da verificare. Controlla condizioni dell’impianto, compatibilità e componenti aggiuntivi prima di confermare.</p><div id="recipe-result" role="status"></div></article>`);
function recipeQuestions(){const id=$('recipe-select').value,r=E.recipes.find(r=>r.id===id),a=state.answers[id];$('recipe-description').textContent=r.description;$('recipe-count').value=a?.count||1;$('recipe-access').value=a?.access||'normal';$('recipe-accessories').value=a?.accessories||'no';$('accessories-label').hidden=!r.accessories.length;$('recipe-memory').textContent=a?'Ultime risposte recuperate dal tuo browser. Modifica solo ciò che cambia.':'Rispondi una volta: ritroverai questi valori la prossima volta.'}
$('recipe-select').onchange=recipeQuestions;recipeQuestions();
$('generate').onclick=()=>{const id=$('recipe-select').value,a={count:Number($('recipe-count').value),access:$('recipe-access').value,accessories:id==='lamp'?'no':$('recipe-accessories').value};if(!$('recipe-count').checkValidity()){toast('Inserisci un numero intero di punti da 1 a 1000.');return}if(draft.lines.length&&!confirm('Sostituire materiali e ore della bozza con questa ricetta?'))return;const policy=$('recipe-policy').value==='default'?state.settings.policy:$('recipe-policy').value;const result=E.generate(id,a,state.catalog,{...state.settings,policy},state.memory);state.answers[id]=a;draft.markupPercent=state.settings.markupPercent;draft.lines=result.lines;draft.hours=result.hours;draft.hourlyRate=state.settings.hourlyRate;draft.laborMode='hourly';draft.job=E.recipes.find(r=>r.id===id).name;draft.recipe={id,answers:a,key:E.key(id,a)};draft.reviewed=false;loadEditor();$('recipe-result').textContent=result.remembered?'Configurazione personale recuperata; prezzi aggiornati dal listino.':'Bozza generata dalla ricetta dimostrativa. Controlla materiali e ore.';recipeQuestions()};
const baseSave=$('save').onclick;
$('save').onclick=async()=>{if(!ready())return;if(draft.recipe&&$('learn-recipe').checked){state.memory[draft.recipe.key]={hours:draft.hours,lines:draft.lines.map(l=>({name:l.name,group:l.group||'',unit:l.unit,qty:l.qty,catalogId:l.catalogId||'',price:l.price})),updatedAt:new Date().toISOString()};memoryView()}await baseSave();};
document.querySelector('.materials').insertAdjacentHTML('beforeend','<p class="helper">Le alternative confrontano solo articoli dello stesso gruppo e unità. Assegna i gruppi dopo aver verificato la compatibilità tecnica.</p>');
const baseRender=renderLines;
renderLines=function(){baseRender();draft.lines.forEach(l=>{const row=Array.from($('lines').rows).find(row=>row.dataset.id===l.id);if(!row)return;const options=E.choices(state.catalog,l.group,l.unit);if(l.group&&options.length){row.cells[0].insertAdjacentHTML('beforeend',`<select class="alternatives" data-alternative="${esc(l.id)}" aria-label="Alternativa per ${esc(l.name)}"><option value="">Cambia alternativa…</option>${options.map(o=>`<option value="${esc(o.item.id)}">${o.label} · ${esc(o.item.name)} · ${euro(E.pricing(o.item,draft.markupPercent??state.settings.markupPercent).price)}</option>`).join('')}</select>`)}if(l.missing)row.cells[0].insertAdjacentHTML('beforeend','<small class="missing">Articolo mancante: completa descrizione e prezzo, poi conferma <button type="button" data-resolve="'+esc(l.id)+'">Voce verificata</button></small>');else if(l.demo)row.cells[0].insertAdjacentHTML('beforeend','<small class="muted">Articolo dimostrativo</small>')})};
$('lines').addEventListener('change',e=>{if(!e.target.dataset.alternative)return;const l=draft.lines.find(l=>l.id===e.target.dataset.alternative),c=state.catalog.find(c=>c.id===e.target.value);if(!c)return;delete l.salePrice;Object.assign(l,{name:c.name,...E.pricing(c,draft.markupPercent??state.settings.markupPercent),catalogId:c.id,missing:false,demo:!!c.demo});renderLines();update()});
$('lines').addEventListener('click',e=>{if(!e.target.dataset.resolve)return;const l=draft.lines.find(l=>l.id===e.target.dataset.resolve);if(!l.name.trim()){toast('Inserisci la descrizione.');return}l.missing=false;renderLines();update()});
const groupOptions=()=>'<option value="">Non classificato</option>'+Object.entries(E.groups).map(([id,name])=>`<option value="${id}">${esc(name)}</option>`).join('');
document.querySelector('#catalog-form').insertAdjacentHTML('afterbegin',`<label>Prezzo vendita (facoltativo)<input name="salePrice" type="number" min="0" max="100000000" step="0.01"></label><label>Codice articolo<input name="sku" placeholder="Codice fornitore"></label><label>Gruppo compatibilità<select name="group">${groupOptions()}</select></label>`);
const oldForm=$('catalog-form').onsubmit;$('catalog-form').onsubmit=e=>{const f=new FormData(e.target),length=state.catalog.length;oldForm(e);if(state.catalog.length>length){const c=state.catalog.at(-1);c.sku=f.get('sku').trim();c.group=f.get('group');if(f.get('salePrice')!=='')c.salePrice=round(Number(f.get('salePrice')));persist();renderCatalog()}};
const baseCatalog=renderCatalog;renderCatalog=function(){baseCatalog();$('catalog-list').querySelectorAll('.catalog-row').forEach(row=>{const c=state.catalog.find(c=>c.id===row.dataset.id);const select=document.createElement('select');select.setAttribute('aria-label','Gruppo compatibilità '+c.name);select.innerHTML=groupOptions();select.value=c.group||'';select.onchange=()=>{c.group=select.value;persist()};row.insertBefore(select,row.lastElementChild);const sale=document.createElement('input');sale.type='number';sale.className='sale-price';sale.min='0';sale.step='0.01';sale.placeholder='Vendita €';sale.setAttribute('aria-label','Prezzo vendita '+c.name);sale.value=c.salePrice??'';sale.onchange=e=>{e.stopPropagation();if(sale.value==='')delete c.salePrice;else c.salePrice=round(Math.min(1e8,Math.max(0,Number(sale.value)||0)));persist()};row.insertBefore(sale,row.lastElementChild);if(c.sku)row.querySelector('span').insertAdjacentHTML('beforeend',`<small class="unit"> · ${esc(c.sku)}</small>`)})};
$('catalog-form').insertAdjacentHTML('beforebegin',`<article class="card import-card"><h2>Importa il listino Excel</h2><p>Scegli un file .xlsx, il foglio e le colonne. I PDF vanno prima convertiti in Excel. I prezzi devono essere unitari, netti e IVA esclusa.</p><input id="excel-file" aria-label="Carica listino Excel" type="file" accept=".xlsx"><div id="excel-map" hidden></div><div id="excel-preview"></div><button id="commit-excel" class="primary" hidden>Conferma importazione</button><p id="excel-status" role="status"></p><button id="demo-catalog" class="secondary">Carica 18 articoli dimostrativi</button><p class="helper">Dati sintetici per provare le tre fasce di prezzo; non prodotti reali né prezzi di mercato.</p></article>`);
$('demo-catalog').onclick=()=>{let n=0;for(const c of E.demoCatalog()){if(!state.catalog.some(x=>x.id===c.id)){state.catalog.push(c);n++}}persist();renderCatalog();renderPicker();toast(`${n} articoli dimostrativi aggiunti.`)};
let workbook,importRows=[];
$('excel-file').onchange=async e=>{workbook=null;importRows=[];$('commit-excel').hidden=true;$('excel-map').hidden=true;$('excel-preview').textContent='';const f=e.target.files[0];if(!f)return;if(!/\.xlsx$/i.test(f.name)||f.size>10*1024*1024){$('excel-status').textContent='Carica un file .xlsx fino a 10 MB. Converti prima eventuali PDF o .xls.';return}try{$('excel-status').textContent='Lettura del file…';workbook=new ExcelJS.Workbook();await workbook.xlsx.load(await f.arrayBuffer());$('excel-map').hidden=false;$('excel-map').innerHTML=`<label>Foglio<select id="excel-sheet">${workbook.worksheets.map((s,i)=>`<option value="${i}">${esc(s.name)}</option>`).join('')}</select></label><label>Riga intestazioni<input id="excel-header" type="number" min="1" max="1000" value="1"></label><div id="column-maps" class="fields"></div><button id="preview-excel" class="secondary">Controlla le righe</button>`;$('excel-sheet').onchange=mapColumns;$('excel-header').onchange=mapColumns;$('preview-excel').onclick=previewExcel;mapColumns();$('excel-status').textContent='Associa le colonne, poi controlla l’anteprima.'}catch{$('excel-status').textContent='File Excel non leggibile. Verifica che non sia protetto o danneggiato.'}};
function cellText(cell){const v=cell.value;if(v&&typeof v==='object'){if('formula'in v||'sharedFormula'in v)return v.result??'';if(v.richText)return v.richText.map(x=>x.text).join('');return v.text??''}return v??''}
function sheet(){return workbook.worksheets[Number($('excel-sheet').value)]}
function mapColumns(){importRows=[];$('commit-excel').hidden=true;$('excel-preview').textContent='';const row=sheet().getRow(Number($('excel-header').value)||1),columns=[];row.eachCell((cell,i)=>columns.push({i,name:String(cellText(cell))}));$('column-maps').innerHTML=[['name','Descrizione',/descr|name|material/i],['price','Costo netto unitario',/costo|acquisto|^prezzo$|^price$/i],['salePrice','Prezzo vendita (facoltativo)',/vendita|sale/i],['unit','Unità',/unit|^um$|u\.m/i],['sku','Codice articolo',/cod|sku/i],['group','Gruppo compatibilità',/grupp/i]].map(([key,label,match])=>`<label>${label}<select id="map-${key}"><option value="">${key==='name'||key==='price'?'Seleziona…':'Non presente'}</option>${columns.map(c=>`<option value="${c.i}" ${match.test(c.name)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`).join('');$('column-maps').onchange=()=>{importRows=[];$('commit-excel').hidden=true;$('excel-preview').textContent='Colonne modificate: ripeti il controllo.'}};
function previewExcel(){importRows=[];const m=Object.fromEntries(['name','price','salePrice','unit','sku','group'].map(k=>[k,Number($('map-'+k).value)]));if(!m.name||!m.price||new Set(Object.values(m).filter(Boolean)).size!==Object.values(m).filter(Boolean).length){$('excel-status').textContent='Associa descrizione e prezzo a colonne diverse, senza duplicati.';return}const s=sheet(),errors=[],seen=new Set();if(s.rowCount>10001){$('excel-status').textContent='Massimo 10.000 righe per importazione.';return}for(let i=Number($('excel-header').value)+1;i<=s.rowCount;i++){const row=s.getRow(i),read=k=>m[k]?cellText(row.getCell(m[k])):'';const name=String(read('name')).trim(),rawPrice=read('price');if(!name&&rawPrice==='')continue;const saleRaw=read('salePrice'),salePrice=saleRaw===''?undefined:E.number(saleRaw);const price=E.number(rawPrice),unit=String(read('unit')).trim().toLowerCase()||'pz',sku=String(read('sku')).trim(),group=String(read('group')).trim();if(!name||!Number.isFinite(price)||price<0||price>1e8||(salePrice!==undefined&&(!Number.isFinite(salePrice)||salePrice<0||salePrice>1e8))||group&&!E.groups[group]||sku&&seen.has(sku)){errors.push(`Riga ${i}: descrizione, prezzo, gruppo o codice duplicato non valido.`);continue}if(sku)seen.add(sku);importRows.push({id:uid(),name,price:round(price),...(salePrice!==undefined?{salePrice:round(salePrice)}:{}),unit,sku,group,source:$('excel-file').files[0].name})}if(state.catalog.length+importRows.filter(c=>!c.sku||!state.catalog.some(x=>x.sku===c.sku)).length>10000)errors.push('Il listino risultante supera 10.000 articoli.');$('excel-preview').innerHTML=`<p>${importRows.length} righe valide · ${errors.length} errori. Mostrate le prime 15 righe.</p><div class="table-scroll"><table><thead><tr><th>Codice</th><th>Descrizione</th><th>Unità</th><th>Costo netto</th><th>Vendita</th><th>Gruppo</th></tr></thead><tbody>${importRows.slice(0,15).map(c=>`<tr><td>${esc(c.sku)}</td><td>${esc(c.name)}</td><td>${esc(c.unit)}</td><td>${euro(c.price)}</td><td>${c.salePrice===undefined?'—':euro(c.salePrice)}</td><td>${esc(c.group||'Da assegnare')}</td></tr>`).join('')}</tbody></table></div><p class="missing">${errors.slice(0,8).map(esc).join('<br>')}</p>`;$('commit-excel').hidden=!!errors.length||!importRows.length;$('excel-status').textContent=errors.length?'Correggi gli errori prima di importare. Nessuna riga è stata caricata.':'I codici già presenti verranno aggiornati; gli altri articoli aggiunti. Senza gruppo verificato non entrano nelle ricette.';if(errors.length)importRows=[]}
$('commit-excel').onclick=()=>{if(!importRows.length)return;for(const c of importRows){const i=c.sku?state.catalog.findIndex(x=>x.sku===c.sku):-1;if(i>=0)state.catalog[i]={...c,id:state.catalog[i].id,group:c.group||''};else state.catalog.push(c)}persist();renderCatalog();renderPicker();$('excel-status').textContent=`${importRows.length} articoli importati. Controlla i gruppi di compatibilità prima di generare.`;importRows=[];$('commit-excel').hidden=true};
renderLines();update();

$('default-policy').parentElement.insertAdjacentHTML('afterend','<label>Ricarico predefinito (%)<input id="default-markup" type="number" min="0" max="10000" step="0.1"></label>');
$('default-markup').value=state.settings.markupPercent;$('default-markup').onchange=()=>{state.settings.markupPercent=Math.min(10000,Math.max(0,Number($('default-markup').value)||0));persist()};
$('hourlyRate').parentElement.insertAdjacentHTML('afterend','<label>Ricarico materiali per questo lavoro (%)<input id="quote-markup" type="number" min="0" max="10000" step="0.1"></label>');
const oldLoad=loadEditor;loadEditor=function(){oldLoad();draft.markupPercent??=state.settings.markupPercent;$('quote-markup').value=draft.markupPercent};
$('quote-markup').onchange=()=>{draft.markupPercent=Math.min(10000,Math.max(0,Number($('quote-markup').value)||0));for(const l of draft.lines){if(l.costPrice!==undefined)l.price=l.salePrice??round(l.costPrice*(1+draft.markupPercent/100))}renderLines();update()};
$('add-material').onclick=()=>{const c=state.catalog.find(c=>c.id===$('material-select').value);if(!c){toast('Scegli prima un materiale.');return}draft.lines.push({...c,...E.pricing(c,draft.markupPercent??state.settings.markupPercent),catalogId:c.id,id:uid(),qty:1});renderLines();update()};
$('lines').addEventListener('input',e=>{if(e.target.dataset.field==='price'){const l=draft.lines.find(l=>l.id===e.target.closest('tr').dataset.id);delete l.costPrice;delete l.salePrice;persist()}});
loadEditor();

$('catalog-form').querySelector('[name=price]').parentElement.firstChild.textContent='Costo netto unitario (€)';
document.querySelector('#settings .card p').textContent+=' Il prezzo di vendita, se presente, prevale sul costo con ricarico. Il ricarico iniziale è 0%: impostalo secondo la tua attività.';
document.querySelector('.materials .helper').textContent+=' Le tre fasce sono ordinate per costo netto. Il prezzo in bozza è quello di vendita, oppure costo più ricarico. Un prezzo modificato a mano resta fisso.';

$('lines').addEventListener('input',e=>{if(e.target.dataset.field==='name'){const l=draft.lines.find(l=>l.id===e.target.closest('tr').dataset.id);delete l.catalogId;delete l.group;delete l.costPrice;delete l.salePrice;delete l.demo;persist()}});
window.addEventListener('bottega-state-loaded',()=>{state.settings??={hourlyRate:100,policy:'median',markupPercent:0};state.memory??={};state.answers??={};$('default-rate').value=state.settings.hourlyRate;$('default-policy').value=state.settings.policy;$('default-markup').value=state.settings.markupPercent??0;memoryView();recipeQuestions()});


